    for trip_id, stops in trip_times.items():
        for stop_id, stop_name in stops.items():
            if stop_id in valid_stops:
                trip_stop_name_map[stop_id] = stop_name

    # Process trip times
    valid_trip_times = []
    invalid_coordinates_removed = 0
duplicate_stops_removed = 0
missing_stop_names_filled = 0
